const fs = require('fs');

const PREFS_FILE = '/home/node/.n8n/preferences.json';

function loadJSON(filePath, defaultData) {
  if (!fs.existsSync(filePath)) {
    fs.writeFileSync(filePath, JSON.stringify(defaultData, null, 2));
    return defaultData;
  }
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function saveJSON(filePath, data) {
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2));
}

function isValidEmail(email) {
  return /^[a-zA-Z0-9][a-zA-Z0-9._-]*@[a-zA-Z0-9][a-zA-Z0-9.-]*\.[a-zA-Z]{2,}$/.test(email);
}

function containsGarbage(val) {
  if (!val) return false;
  if (val.includes('|')) return true;
  if (val.includes(',')) return true;
  if (/save_preferences|get_preferences|update_setting|unsubscribe/.test(val)) return true;
  return false;
}

const VALID_TOPICS = [
  'tech', 'ai', 'science', 'sport', 'politique', 'economie', 'sante',
  'culture', 'environnement', 'espace', 'startup', 'dev', 'securite',
  'jeux-video', 'musique', 'cinema', 'education', 'international'
];

const VALID_SOURCES = [
  'techcrunch', 'bbc', 'the-verge', 'nasa', 'hacker-news',
  'le-monde', 'wired', 'ars-technica', 'reuters', 'associated-press'
];

const VALID_FREQUENCIES = ['daily', 'weekly', 'weekdays'];

const VALID_FORMATS = ['html', 'plaintext'];

const input = $input.first().json;
const rawQuery = (input.query || '').toString().split('|')[0];
const params = rawQuery.split(',').map(p => p.trim());
const action = params[0];
const userId = params[1];

const data = loadJSON(PREFS_FILE, { preferences: [] });

// --- GET PREFERENCES ---
if (action === 'get_preferences') {
  if (!userId) return [{ json: { response: 'ERROR: userId required' } }];
  const prefs = data.preferences.find(p => p.userId === userId);
  if (!prefs) return [{ json: { response: 'NO_PREFERENCES', data: null } }];
  return [{
    json: {
      response: 'FOUND',
      data: {
        topics: prefs.topics || [],
        email: prefs.email || '',
        scheduleTime: prefs.scheduleTime || '',
        timezone: prefs.timezone || 'Africa/Porto-Novo',
        articleCount: prefs.articleCount || 5,
        frequency: prefs.frequency || 'daily',
        sources: prefs.sources || [],
        emailFormat: prefs.emailFormat || 'html',
        customPrompt: prefs.customPrompt || '',
        active: prefs.active !== false
      }
    }
  }];
}

// --- SAVE CORE PREFERENCES ---
if (action === 'save_preferences') {
  const topics = params[2] ? params[2].split('|').map(t => t.trim().toLowerCase()).filter(t => t) : [];
  const email = params[3];
  const scheduleTime = params[4];
  const timezone = params[5] || 'Africa/Porto-Novo';

  if (!userId) return [{ json: { response: 'ERROR: userId required' } }];
  if (!email || containsGarbage(email) || !isValidEmail(email)) return [{ json: { response: 'ERROR: valid email required (got: ' + (email || '') + ')' } }];
  if (!scheduleTime || containsGarbage(scheduleTime) || !/^\d{2}:\d{2}$/.test(scheduleTime)) return [{ json: { response: 'ERROR: scheduleTime must be HH:MM (got: ' + (scheduleTime || '') + ')' } }];
  if (topics.length === 0) return [{ json: { response: 'ERROR: at least one topic required. Valid topics: ' + VALID_TOPICS.join(', ') } }];

  const existing = data.preferences.findIndex(p => p.userId === userId);
  const entry = {
    userId,
    topics,
    email: email.trim().toLowerCase(),
    scheduleTime,
    timezone,
    articleCount: 5,
    frequency: 'daily',
    sources: [],
    emailFormat: 'html',
    customPrompt: '',
    active: true,
    updatedAt: new Date().toISOString()
  };

  if (existing >= 0) {
    data.preferences[existing] = { ...data.preferences[existing], ...entry, createdAt: data.preferences[existing].createdAt };
  } else {
    entry.createdAt = new Date().toISOString();
    data.preferences.push(entry);
  }

  saveJSON(PREFS_FILE, data);
  return [{ json: { response: 'SUCCESS: Core preferences saved', data: entry } }];
}

// --- UPDATE INDIVIDUAL SETTING ---
if (action === 'update_setting') {
  const setting = params[2];
  const value = params.slice(3).join(',');

  if (!userId || !setting) return [{ json: { response: 'ERROR: userId and setting name required' } }];
  if (containsGarbage(value)) return [{ json: { response: 'ERROR: value contains invalid characters (| or , or action keywords)' } }];

  let existing = data.preferences.findIndex(p => p.userId === userId);
  if (existing < 0) return [{ json: { response: 'ERROR: no preferences found. Save core prefs first.' } }];

  const aliases = { heure: 'scheduleTime' };
  const resolvedSetting = aliases[setting] || setting;

  const validSettings = ['topics', 'email', 'scheduleTime', 'timezone', 'articleCount', 'frequency', 'sources', 'emailFormat', 'customPrompt'];

  if (!validSettings.includes(resolvedSetting)) {
    return [{ json: { response: 'ERROR: invalid setting. Valid: ' + validSettings.join(', ') + '. Aliases: heure=scheduleTime' } }];
  }

  let parsedValue = value;

  if (resolvedSetting === 'topics' || resolvedSetting === 'sources') {
    parsedValue = value.split('|').map(v => v.trim().toLowerCase()).filter(v => v);
  }
  if (resolvedSetting === 'articleCount') {
    const n = parseInt(value);
    if (isNaN(n) || n < 1 || n > 20) return [{ json: { response: 'ERROR: articleCount must be between 1 and 20' } }];
    parsedValue = n;
  }
  if (resolvedSetting === 'frequency') {
    if (!VALID_FREQUENCIES.includes(value.toLowerCase())) return [{ json: { response: 'ERROR: frequency must be daily, weekly, or weekdays' } }];
    parsedValue = value.toLowerCase();
  }
  if (resolvedSetting === 'emailFormat') {
    if (!VALID_FORMATS.includes(value.toLowerCase())) return [{ json: { response: 'ERROR: emailFormat must be html or plaintext' } }];
    parsedValue = value.toLowerCase();
  }
  if (resolvedSetting === 'email') {
    if (containsGarbage(value) || !isValidEmail(value)) return [{ json: { response: 'ERROR: valid email required' } }];
    parsedValue = value.trim().toLowerCase();
  }
  if (resolvedSetting === 'scheduleTime') {
    if (!/^\d{2}:\d{2}$/.test(value)) return [{ json: { response: 'ERROR: scheduleTime must be HH:MM' } }];
    parsedValue = value;
  }

  data.preferences[existing][resolvedSetting] = parsedValue;
  data.preferences[existing].updatedAt = new Date().toISOString();
  saveJSON(PREFS_FILE, data);

  return [{ json: { response: 'SUCCESS: ' + resolvedSetting + ' updated to ' + JSON.stringify(parsedValue) } }];
}

// --- UNSUBSCRIBE ---
if (action === 'unsubscribe') {
  if (!userId) return [{ json: { response: 'ERROR: userId required' } }];
  const prefs = data.preferences.find(p => p.userId === userId);
  if (prefs) {
    prefs.active = false;
    prefs.updatedAt = new Date().toISOString();
    saveJSON(PREFS_FILE, data);
  }
  return [{ json: { response: 'SUCCESS: Unsubscribed' } }];
}

return [{ json: { response: 'ERROR: unknown action. Available: get_preferences, save_preferences, update_setting, unsubscribe' } }];
